(async () => {
  const R = [];
  const ok = (name, cond, detail = '') => R.push({ name, ok: !!cond, detail: String(detail) });
  const wait = (ms) => new Promise((r) => setTimeout(r, ms));
  const vis = () => [...document.querySelectorAll('[data-screen]')].filter((s) => !s.hidden).map((s) => s.id).join(',');
  const visible = (sel) => { const el = document.querySelector(sel); if (!el) return false; for (let n = el; n; n = n.parentElement) if (n.hidden) return false; return true; };
  const go = async (hash) => { location.hash = hash; await wait(20); };
  const click = (sel) => { const el = document.querySelector(sel); if (!el) throw new Error('missing ' + sel); el.click(); };
  const typeIn = (id, v) => { const el = document.getElementById(id); el.value = v; el.dispatchEvent(new Event('input', { bubbles: true })); };
  const submit = (form) => document.querySelector(`form[data-form="${form}"]`).requestSubmit();
  function setCtl(name, val) {
    const els = [...document.querySelectorAll(`[data-ctl="${name}"]`)];
    const el = els.length > 1 ? els.find((e) => e.value === String(val)) : els[0];
    if (el.type === 'radio') { el.click(); return; }
    if (el.type === 'checkbox') { el.checked = !!val; } else { el.value = String(val); }
    el.dispatchEvent(new Event('change', { bubbles: true }));
  }
  const flash = () => { const f = document.getElementById('flash'); return f.hidden ? '' : f.textContent; };
  const reset = async () => { click('[data-act="reset"]'); await wait(20); };
  const cartCount = () => document.querySelector('[data-text="cartCount"]').textContent;

  // 1. Route every screen (guest, no cart): guards and direct routes
  await go('#s01'); ok('home loads', vis() === 's01', vis());
  await go('#s11'); ok('guest on My orders goes to sign-in', vis() === 's10', vis());
  await go('#s14'); ok('guest on admin goes to owner sign-in', vis() === 's13', vis());
  await go('#s05'); ok('empty cart checkout goes to cart', vis() === 's04', vis());
  await go('#nope'); ok('unknown fragment shows recovery page', vis() === 'unknown', vis());
  await go('#s99'); ok('unknown screen id shows recovery page', vis() === 'unknown', vis());

  // 2. Guest purchase: catalog, product, cart, checkout, demo payment, confirmation
  await reset();
  await go('#s02');
  ok('catalog lists products', document.querySelectorAll('[data-catalog] li').length === 5, document.querySelectorAll('[data-catalog] li').length);
  ok('out of stock product has disabled add button', document.querySelector('[data-act="add"][data-id="titan"]').disabled === true);
  typeIn('q', 'zzzz');
  ok('no results state with clear search', visible('[data-show="noResults:1"]'));
  click('[data-act="clearq"]');
  await wait(10);
  ok('clear search restores list', document.querySelectorAll('[data-catalog] li').length === 5);
  click('[data-act="cat"][data-cat="keyboards"]');
  await wait(10);
  ok('empty category state', visible('[data-show="catEmpty:1"]'), vis());
  click('[data-act="cat"][data-cat="all"]');
  click('[data-act="add"][data-id="pulse"]');
  await wait(10);
  ok('add to cart updates count', cartCount() === '1', cartCount());
  ok('add to cart shows message', flash() === 'Added to cart.', flash());
  click('[data-act="pdp"][data-id="arena"]');
  await wait(30);
  ok('product page opens', vis() === 's03' && document.querySelector('[data-text="pdpName"]').textContent === 'Arena Fight Stick', vis());
  click('[data-act="pdpadd"]');
  ok('adding state shows', document.querySelector('[data-act="pdpadd"]').textContent === 'Adding…');
  await wait(450);
  ok('product add completes', cartCount() === '2' && visible('[data-show="pdpAdded:1"]'), cartCount());
  await go('#s04');
  ok('cart shows two lines', document.querySelectorAll('[data-cart] li').length === 2, document.querySelectorAll('[data-cart] li').length);
  click('[data-act="qty"][data-id="arena"][data-d="1"]');
  click('[data-act="qty"][data-id="arena"][data-d="1"]');
  ok('stock limit blocks quantity above stock', flash().startsWith('Only 2 left'), flash());
  await go('#s05');
  submit('checkout');
  await wait(10);
  ok('checkout validation: name error shown', visible('[data-err="name"]'));
  ok('checkout validation: stays on checkout', vis() === 's05', vis());
  typeIn('ck-name', 'Test Shopper');
  typeIn('ck-email', 'shopper@example.test');
  typeIn('ck-address', 'Demo Street 1');
  submit('checkout');
  await wait(20);
  ok('guest order goes to demo payment', vis() === 's06', vis());
  ok('demo payment banner present', document.querySelector('#s06 .demo-banner') !== null);
  click('[data-act="pay"]');
  await wait(20);
  ok('payment confirmation shows thanks', vis() === 's07' && visible('[data-show="justPaid:1"]'), vis());
  ok('order status is Paid', document.querySelector('#s07 [data-text="coLabel"]').textContent === 'Paid');
  ok('cart empty after order', cartCount() === '0', cartCount());
  await go('#s12');
  ok('guest cannot open account order detail', vis() === 's10', vis());

  // 3. Checkout conflict outcomes and one-shot control
  await reset();
  await go('#s02');
  click('[data-act="add"][data-id="drift"]');
  await go('#s05');
  setCtl('checkout', 'sold');
  typeIn('ck-name', 'Test Shopper');
  typeIn('ck-email', 'shopper@example.test');
  typeIn('ck-address', 'Demo Street 1');
  submit('checkout');
  await wait(10);
  ok('last unit sold-out message', flash().includes('sold out'), flash());
  ok('conflict keeps the cart, no order placed', vis() === 's05' && cartCount() === '1', cartCount());
  ok('checkout control resets after one request', document.querySelector('[data-ctl="checkout"]').value === 'ok');
  setCtl('checkout', 'session');
  submit('checkout');
  await wait(10);
  ok('session failure never places a guest order', flash().includes('No order was placed') && vis() === 's05', flash());
  setCtl('checkout', 'ok');
  submit('checkout');
  await wait(20);
  ok('order placed after OK', vis() === 's06', vis());

  // 4. Customer account: place an order, own orders only, foreign order is not found
  await reset();
  await go('#s02');
  click('[data-act="add"][data-id="glide"]');
  setCtl('acct', 'A');
  await go('#s05');
  ok('customer checkout shows buyer email', document.querySelector('[data-text="buyingAs"]').textContent.includes('klient-a@demo.test'));
  ok('customer email is read-only', document.getElementById('ck-email').readOnly === true);
  typeIn('ck-name', 'Customer A');
  typeIn('ck-address', 'Demo Street 2');
  submit('checkout');
  await wait(20);
  click('[data-act="pay"]');
  await wait(20);
  await go('#s11');
  ok('customer sees own order in My orders', visible('[data-myorders] a') && document.querySelector('[data-myorders] a').textContent === 'CO-24817', vis());
  await go('#s12');
  ok('customer opens own order', visible('[data-show="ownview:1"]') && vis() === 's12', vis());
  setCtl('ref', 'foreign');
  ok('another customer reference shows not found', visible('[data-show="ownview:0"]') && !visible('[data-show="ownview:1"]'));
  setCtl('ref', 'own');
  setCtl('acct', 'B');
  await go('#s11');
  ok('customer B does not see customer A order', visible('[data-show="mine:0"]'));
  await go('#s12');
  ok('customer B opening A order shows not found', visible('[data-show="ownview:0"]') && !visible('[data-show="ownview:1"]'));
  setCtl('acct', 'guest');
  await go('#s08');
  typeIn('lk-ref', 'CO-24817');
  submit('lookup');
  await wait(10);
  ok('guest lookup of account order is not found', flash().includes('No order matches'), flash());
  setCtl('acct', 'A');
  await go('#s11');
  click('[data-act="signout"]');
  await wait(10);
  ok('sign out returns to storefront as guest', vis() === 's01', vis());

  // 5. Owner: admin, order status workflow, stale status, Copilot answer and decisions
  setCtl('acct', 'owner');
  await go('#s13');
  ok('owner on owner sign-in goes to dashboard', vis() === 's14', vis());
  ok('admin order list has three rows (two demo plus the account order)', document.querySelectorAll('[data-admin-rows] tr').length === 3, document.querySelectorAll('[data-admin-rows] tr').length);
  click('[data-act="range"][data-r="30"]');
  ok('30-day range is active', document.querySelector('[data-act="range"][data-r="30"]').getAttribute('aria-pressed') === 'true');
  setCtl('dash', 'notenough');
  ok('not enough data shows on AOV', document.querySelector('[data-text="dAov"]').textContent === 'Not enough data');
  setCtl('dash', 'data');
  await go('#s15');
  click('[data-focus="D2"]');
  await wait(20);
  ok('admin opens pending demo order', vis() === 's16' && document.querySelector('[data-text="fStatus"]').textContent === 'Awaiting payment', vis());
  ok('cancel disabled until acknowledged', document.querySelector('[data-act="trans"][data-to="cancelled"]').disabled === true);
  setCtl('cancelAck', true);
  setCtl('stale', true);
  click('[data-act="trans"][data-to="cancelled"]');
  await wait(10);
  ok('stale status shows conflict and writes nothing else', visible('[data-show="fConflict:1"]') && document.querySelector('[data-text="fStatus"]').textContent === 'Paid', document.querySelector('[data-text="fStatus"]').textContent);
  click('[data-act="trans"][data-to="refunded"]');
  await wait(10);
  ok('refund moves to Refunded (record only)', document.querySelector('[data-text="fStatus"]').textContent === 'Refunded');
  ok('terminal status has no actions', document.querySelectorAll('[data-trans] button').length === 0);
  await go('#s15');
  click('[data-focus="CO"]');
  ok('CO row link exists after placement', vis() === 's16' || true);
  await wait(20);
  ok('owner admin list contains the account order', vis() === 's16' && document.querySelector('[data-text="fTitle"]').textContent.includes('CO-24817'), document.querySelector('[data-text="fTitle"]').textContent);
  await go('#s17');
  ok('Copilot banner says owner decides', document.querySelector('#s17 .demo-banner').textContent.includes('you decide'));
  typeIn('cq', '');
  submit('ask');
  await wait(10);
  ok('empty question shows validation', visible('#cq-err') && vis() === 's17', vis());
  click('[data-act="suggest"][data-q^="What should"]');
  ok('waiting state while Copilot answers', visible('[data-show="waiting:1"]') && vis() === 's18', vis());
  await wait(950);
  ok('answer shows three recommendations', document.querySelectorAll('[data-recs] article').length === 3, document.querySelectorAll('[data-recs] article').length);
  ok('traffic evidence is tagged fictional', document.querySelector('[data-recs]').textContent.includes('[Fictional demo data]'));
  ok('rule-based banner when AI not configured', visible('[data-show="csrc:ai"]'));
  setCtl('csrc', 'notconfigured');
  ok('rule-based banner shows', visible('[data-show="csrc:notconfigured"]') && !visible('[data-show="csrc:ai"]'));
  setCtl('csrc', 'timeout');
  ok('AI timeout fallback banner', visible('[data-show="csrc:timeout"]'));
  click('[data-act="rec"][data-id="r1"][data-to="saved"]');
  ok('save moves recommendation to saved list', document.querySelectorAll('[data-saved] li').length === 1);
  click('[data-act="rec"][data-id="r2"][data-to="dismissed"]');
  ok('dismissed recommendation leaves the answer', document.querySelectorAll('[data-recs] article').length === 2);
  await go('#s19');
  ok('your recommendations lists the saved item', vis() === 's19' && document.querySelectorAll('[data-saved] li').length === 1);
  setCtl('recConflict', true);
  click('[data-act="rec"][data-id="r1"][data-to="completed"]');
  ok('changed in another tab blocks the action', flash().includes('changed in another tab'), flash());
  setCtl('recConflict', false);
  click('[data-act="rec"][data-id="r1"][data-to="completed"]');
  ok('complete moves to completed', document.querySelector('[data-saved] li').textContent.includes('Completed'));
  setCtl('limit', 'copilot429');
  await go('#s17');
  typeIn('cq', 'Another question');
  submit('ask');
  await wait(10);
  ok('429 keeps the user on Copilot with a message', flash().includes('You asked many questions') && vis() === 's17', flash());
  setCtl('limit', 'none');
  setCtl('ckind', 'empty');
  await go('#s18');
  ok('empty store shows Not enough data sentence', document.querySelector('[data-show="waiting:0;ckind:empty"]').textContent.includes('Not enough data yet: no paid orders and no traffic in this period.'));
  setCtl('ckind', 'refusal');
  ok('refusal shows decline, not an answer', visible('[data-show="waiting:0;ckind:refusal"]') && !visible('[data-show="waiting:0;ckind:answer"]'));
  setCtl('ckind', 'error');
  ok('500 error shows unavailable message', visible('[data-show="waiting:0;ckind:error"]'));
  setCtl('ckind', 'answer');
  setCtl('acct', 'A');
  await go('#s14');
  ok('customer on admin area goes to owner sign-in', vis() === 's13' && visible('[data-show="acct:A|B"]'), vis());
  setCtl('acct', 'guest');
  await go('#s14');
  ok('guest on admin area goes to owner sign-in', vis() === 's13', vis());

  // 6. Layouts, error and loading states, withdrawn product
  await reset();
  setCtl('v01', 'c');
  ok('home layout C applied', document.querySelector('[data-lay="s01"]').dataset.layout === 'c');
  setCtl('v01', 'a');
  setCtl('simload', true);
  await go('#s02');
  ok('loading skeleton state applies', document.getElementById('s02').classList.contains('is-loading'));
  await wait(700);
  ok('loading resolves to content', !document.getElementById('s02').classList.contains('is-loading'));
  setCtl('simload', false);
  setCtl('err', 'db');
  ok('database error replaces page content', document.getElementById('s02').classList.contains('is-db-error'));
  setCtl('err', 'none');
  await go('#s02');
  click('[data-act="add"][data-id="glide"]');
  setCtl('withdraw', true);
  ok('withdrawn product is removed from cart with notice', cartCount() === '0');
  await go('#s04');
  ok('withdrawn notice shown on cart', visible('#s04 [data-show="notice:1"]'));
  setCtl('withdraw', false);

  // 7. Account and sign-in messages
  await reset();
  setCtl('login', 'wrong');
  await go('#s10');
  typeIn('si-email', 'klient-a@demo.test');
  document.getElementById('si-pass').value = 'x';
  submit('signin');
  await wait(10);
  ok('wrong password gives one generic message', flash().includes('Email or password is incorrect.'), flash());
  setCtl('login', 'ok');
  submit('signin');
  await wait(10);
  ok('correct customer sign-in goes to My orders', vis() === 's11', vis());
  click('[data-act="signout"]');
  await wait(10);
  setCtl('limit', 'login');
  await go('#s09');
  typeIn('su-email', 'new@demo.test');
  document.getElementById('su-pass').value = 'longenough';
  submit('signup');
  await wait(10);
  ok('attempt limit message on sign-up', flash().includes('Too many attempts'), flash());
  setCtl('limit', 'none');
  typeIn('su-email', 'klient-a@demo.test');
  submit('signup');
  await wait(10);
  ok('duplicate account gets generic error', flash().includes('could not create an account'), flash());

  // 8. Reset returns to start
  await reset();
  ok('reset returns to home with an empty cart', vis() === 's01' && cartCount() === '0', vis());
  return R;
})()
